-- 文件用途：习惯 RPC 权限、幂等、04:00 归日、原始精度、版本冲突及清除恢复契约；事务回滚。
begin;
create extension if not exists pgtap with schema extensions;
select plan(15);
insert into auth.users(id, email) values ('97000000-0000-0000-0000-000000000001', 'habits-one@example.test'), ('97000000-0000-0000-0000-000000000002', 'habits-two@example.test');
select ok(not has_table_privilege('anon', 'public.habit_entries', 'SELECT'), 'Anonymous cannot read');
select ok(not has_table_privilege('authenticated', 'public.habit_entries', 'INSERT'), 'Direct insert denied');
select ok(not has_table_privilege('authenticated', 'public.habit_entry_revisions', 'UPDATE'), 'Revisions immutable to clients');
set local role authenticated;
select set_config('request.jwt.claim.sub', '97000000-0000-0000-0000-000000000001', true);
select lives_ok($$select public.apply_habit_entries('97000000-0000-0000-0000-000000000011', '[{"mode":"record","kind":"sleep","occurred_at":"2020-01-02T00:20:12.345Z"}]', 'UTC', 0)$$, 'First record accepted');
select is((select business_date from public.habit_entries limit 1), date '2020-01-01', 'Midnight sleep belongs to prior business day');
select is((select occurred_at from public.habit_entries limit 1), timestamptz '2020-01-02T00:20:12.345Z', 'Raw milliseconds preserved');
select public.apply_habit_entries('97000000-0000-0000-0000-000000000011', '[{"mode":"record","kind":"sleep","occurred_at":"2020-01-02T00:20:12.345Z"}]', 'UTC', 0);
select is((select count(*) from public.habit_entry_revisions), 1::bigint, 'Retry is idempotent');
select public.apply_habit_entries('97000000-0000-0000-0000-000000000012', '[{"mode":"record","kind":"sleep","occurred_at":"2020-01-02T01:00:00Z"}]', 'UTC', 0);
select is((select occurred_at from public.habit_entries limit 1), timestamptz '2020-01-02T00:20:12.345Z', 'Duplicate click cannot replace first time');
select throws_ok(format('select public.apply_habit_entries(%L, %L::jsonb, %L, 0)', gen_random_uuid(), jsonb_build_array(jsonb_build_object('mode','clear','kind','sleep','id',(select id from public.habit_entries limit 1),'expected_version',0)), 'UTC'), 'P0001', 'HABIT_CONFLICT_ENTRY', 'Stale edit rejected');
select public.apply_habit_entries(gen_random_uuid(), jsonb_build_array(jsonb_build_object('mode','clear','kind','sleep','id',(select id from public.habit_entries limit 1),'expected_version',1)), 'UTC', 0);
select ok((select deleted_at is not null from public.habit_entries limit 1), 'Clear preserves tombstone');
select public.apply_habit_entries(gen_random_uuid(), jsonb_build_array(jsonb_build_object('mode','restore','kind','sleep','id',(select id from public.habit_entries limit 1),'expected_version',2)), 'UTC', 0);
select is((select version from public.habit_entries limit 1), 3, 'Restore advances version');
select is((select snapshot->>'occurred_at' from public.habit_entry_revisions order by id limit 1)::timestamptz, timestamptz '2020-01-02T00:20:12.345Z', 'Original revision survives clear and restore');
select public.configure_habits('Asia/Shanghai', 'UTC', '{"wake_target":420,"sleep_target":1390,"sleep_late":1450,"sleep_very_late":1480}', 0, '97000000-0000-0000-0000-000000000013');
select is((select timezone from public.habit_entries limit 1), 'UTC', 'Timezone setting does not move history');
select is((select effective_from from public.habit_rule_versions where id = (select rule_id from public.habit_entries limit 1)), date '0001-01-01', 'History retains initial rule');
select set_config('request.jwt.claim.sub', '97000000-0000-0000-0000-000000000002', true);
select is((select count(*) from public.habit_entries), 0::bigint, 'Other account cannot read entries');
select * from finish();
rollback;
